from pathlib import Path
import re

layout = Path('/home/ubuntu/meta-ads-command-center/client/src/components/DashboardLayout.tsx')
s = layout.read_text()
s = s.replace('مراقبة المخزون والكميات', 'تقرير الخامات والكميات')
layout.write_text(s)

tasks = Path('/home/ubuntu/meta-ads-command-center/client/src/pages/Tasks.tsx')
s = tasks.read_text()
pattern = r'\{canAssignTasks && <section className="grid gap-6 lg:grid-cols-\[1\.2fr_0\.8fr\]">.*?</section>\}'
s, n = re.subn(pattern, '', s, count=1, flags=re.S)
if n != 1:
    raise SystemExit(f'workload section not found: {n}')
tasks.write_text(s)

sales = Path('/home/ubuntu/meta-ads-command-center/client/src/pages/SalesCollections.tsx')
s = sales.read_text()
marker = '  return <DashboardLayout>'
insert = '''  if (isExecutiveViewer) {\n    const postedSales = sales.filter((item) => item.status === "posted");\n    const totalSales = postedSales.reduce((sum, item) => sum + Number(item.totalAmount || 0), 0);\n    const totalCollected = collections.filter((item) => item.status === "received").reduce((sum, item) => sum + Number(item.amount || 0), 0);\n    const outstanding = Math.max(0, totalSales - totalCollected);\n    const projectRows = projects.map((project) => { const projectSales = postedSales.filter((item) => item.projectId === project.id); const value = projectSales.reduce((sum, item) => sum + Number(item.totalAmount || 0), 0); const collected = collections.filter((item) => item.status === "received" && projectSales.some((sale) => sale.id === item.saleId)).reduce((sum, item) => sum + Number(item.amount || 0), 0); return { project, value, collected, outstanding: Math.max(0, value - collected), count: projectSales.length }; }).filter((row) => row.count);\n    const executiveSales = <div dir="rtl" className="min-h-screen bg-[#f7f8fa] px-4 py-6 sm:px-8 lg:px-10"><div className="mx-auto max-w-7xl space-y-6"><header><Button variant="ghost" className="mb-2 gap-2 px-0 text-slate-500" onClick={() => setLocation("/")}><ArrowRight className="h-4 w-4" /> العودة للوحة التنفيذ</Button><p className="text-sm font-semibold text-[#b28a3b]">مركز القيادة المالية</p><h1 className="text-3xl font-bold text-[#18324b]">لوحة مبيعات المشاريع</h1><p className="mt-2 text-sm text-slate-500">قراءة تنفيذية للمبيعات والتحصيلات والذمم، دون صلاحية إنشاء أو تعديل أو تسجيل سندات قبض.</p></header><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded-2xl bg-white p-5 shadow-sm"><p className="text-sm text-slate-500">إجمالي المبيعات</p><p className="mt-2 text-2xl font-bold text-[#18324b]">{money.format(totalSales)} <small>ر.س</small></p><p className="mt-2 text-xs text-slate-400">{postedSales.length} فاتورة مرحّلة</p></div><div className="rounded-2xl bg-emerald-50 p-5 shadow-sm"><p className="text-sm text-emerald-700">إجمالي التحصيل</p><p className="mt-2 text-2xl font-bold text-emerald-800">{money.format(totalCollected)} <small>ر.س</small></p></div><div className="rounded-2xl bg-amber-50 p-5 shadow-sm"><p className="text-sm text-amber-700">الذمم المتبقية</p><p className="mt-2 text-2xl font-bold text-amber-800">{money.format(outstanding)} <small>ر.س</small></p></div><div className="rounded-2xl bg-[#18324b] p-5 text-white shadow-sm"><p className="text-sm text-slate-200">نسبة التحصيل</p><p className="mt-2 text-2xl font-bold">{totalSales ? Math.round((totalCollected / totalSales) * 100) : 0}%</p><p className="mt-2 text-xs text-slate-300">من الفواتير المرحّلة</p></div></div><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#18324b]">أداء المبيعات والتحصيل حسب المشروع</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-right text-sm"><thead><tr className="border-b bg-[#f5f0e5] text-[#18324b]"><th className="p-3">المشروع</th><th className="p-3">عدد الفواتير</th><th className="p-3">المبيعات</th><th className="p-3">المحصل</th><th className="p-3">المتبقي</th><th className="p-3">التحصيل</th></tr></thead><tbody>{projectRows.map((row) => <tr key={row.project.id} className="border-b last:border-0"><td className="p-3 font-semibold">{row.project.name}</td><td className="p-3">{row.count}</td><td className="p-3">{money.format(row.value)} ر.س</td><td className="p-3 text-emerald-700">{money.format(row.collected)} ر.س</td><td className="p-3 text-amber-700">{money.format(row.outstanding)} ر.س</td><td className="p-3"><div className="h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${row.value ? Math.min(100, (row.collected / row.value) * 100) : 0}%` }} /></div><span className="mt-1 block text-xs text-slate-500">{row.value ? Math.round((row.collected / row.value) * 100) : 0}%</span></td></tr>)}</tbody></table>{!projectRows.length && <p className="py-10 text-center text-sm text-slate-500">لا توجد مبيعات مرحّلة مرتبطة بالمشاريع حتى الآن.</p>}</div></CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#18324b]">آخر حركة مبيعات وتحصيلات</CardTitle></CardHeader><CardContent className="space-y-2">{[...postedSales.map((item) => ({ label: `فاتورة بيع — ${item.customerName}`, amount: Number(item.totalAmount || 0), date: item.saleDate })), ...collections.filter((item) => item.status === "received").map((item) => ({ label: `تحصيل — ${item.customerName || "عميل"}`, amount: Number(item.amount || 0), date: item.collectionDate }))].slice(-8).reverse().map((item, index) => <div key={`${item.label}-${index}`} className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 text-sm"><span>{item.label}</span><span className="font-bold text-[#18324b]">{money.format(item.amount)} ر.س · {String(item.date || "—").slice(0, 10)}</span></div>)}</CardContent></Card></div></div>;\n    return <DashboardLayout>{executiveSales}</DashboardLayout>;\n  }\n'''
if marker not in s:
    raise SystemExit('sales return marker not found')
s = s.replace(marker, insert + marker, 1)
sales.write_text(s)
